    <header>
        <h1>MapleSure SponsorConnect</h1>
    </header>
    <form id="claim-form">
        <label for="policy-number">Policy Number:</label>
        <input type="text" id="policy-number" aria-required="true">
        <label for="member-id">Member ID:</label>
        <input type="text" id="member-id" aria-required="true">
        <button type="button" onclick="lookupMember()" aria-label="Look up member by ID">Look up member</button>
        <div id="member-details" aria-live="polite"></div>
        <label for="last-day-worked">Last Day Worked:</label>
        <input type="date" id="last-day-worked" aria-required="true">
        <label for="first-day-absent">First Day Absent:</label>
        <input type="date" id="first-day-absent" aria-required="true">
        <label for="nature-of-absence">Nature of Absence:</label>
        <select id="nature-of-absence" aria-required="true">
            <option value="illness">Illness</option>
            <option value="injury">Injury</option>
            <option value="personal">Personal Reason</option>
        </select>
        <label for="details">Details:</label>
        <textarea id="details" rows="4"></textarea>
        <label for="documents">Upload Documents:</label>
        <input type="file" id="documents" multiple aria-label="Upload documents" onchange="updateFileList()">
        <ul id="file-list" class="file-list" aria-live="polite"></ul>
        <input type="submit" value="Submit" onclick="submitForm(event)">
    </form>
    <div id="confirmation" aria-live="assertive">
        <h2>Claim Submission</h2>
        <p id="confirmation-msg"></p>
    </div>
    <div class="footer">
        <p>MapleSure Insurance — fictional demo application</p>
    </div>
    <script>
        const mockData = {
            "12345": "John Doe",
            "67890": "Jane Smith"
        };

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');
            if (mockData[memberId]) {
                memberDetails.textContent = `Member Name: ${mockData[memberId]}`;
            } else {
                memberDetails.textContent = 'Member not found';
            }
        }

        function updateFileList() {
            const input = document.getElementById('documents');
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            Array.from(input.files).forEach(file => {
                const li = document.createElement('li');
                li.textContent = file.name;
                fileList.appendChild(li);
            });
        }

        function submitForm(event) {
            event.preventDefault();
            document.getElementById('claim-form').style.display = 'none';
            const confirmation = document.getElementById('confirmation');
            const referenceNumber = `MS-2026-08-${Math.floor(1000 + Math.random() * 9000)}`;
            document.getElementById('confirmation-msg').textContent = `Reference Number: ${referenceNumber} - Status: Received`;
            confirmation.style.display = 'block';
        }
    </script>
</body>
